import{_ as o,l,o as a,c as s,v as t,p as n,x as i,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"SQLite 架构","description":"","frontmatter":{"title":"SQLite 架构","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sqlite-architecture.md","filePath":"cs/sqlite-architecture.md","lastUpdated":1789023840000}'),h={name:"cs/sqlite-architecture.md"};function A(_,e,S,u,L,P){const r=l("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="sqlite-架构" tabindex="-1">SQLite 架构 <a class="header-anchor" href="#sqlite-架构" aria-label="Permalink to &quot;SQLite 架构&quot;">​</a></h1><div class="epigraph"><p>库即文件：B+ 页、回滚日志或 WAL、嵌入进程。无服务器、无连接池网关，锁在文件粒度上从简，SQL 仍声明。</p><footer>—— 据 Hipp SQLite 设计；Gray 嵌入式；影子/WAL 对照</footer></div><p><a href="/cs/search-engine-index">上一课</a>是集群搜索。本课相反极端：SQLite 嵌入式。数据模型族封口。缺口是把本课程机制在<strong>单文件、少线程</strong>上收束：页与槽、B+、WAL 模式、锁、查询规划器简化。分析与流单元从星型模式再开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>进程内 <code>sqlite3_open</code>，无守护进程。并发：默认写锁库级（历史 rollback journal）；WAL 模式读不挡写但仍单写者。缺口是<strong>适用</strong>：移动、应用文件、测试、边缘。不是 NewSQL。规划器：基于代价但连接枚举有限，无分布式 shuffle。</p><p>VFS：把页 I/O 接到 OS，TDE 可在 VFS 做。备份：拷文件要注意检查点。</p><p><span class="marginnote">D. Richard Hipp。SQLite 文档对事务与 WAL 很清楚。本课对照课程树，不背 C API。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模式仍是表与索引。类型亲和。JSON 函数让文档进单元格。FTS 虚表接倒排。不替代 Postgres 服务器。</p><p>与 ORM：常直接 SQL。连接池无意义（同进程），但多线程要 per-connection 或 serialized 模式。</p>',10)),(a(),n(p,null,{default:i(()=>[d(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%BA%94%E7%94%A8%E7%BA%BF%E7%A8%8B%22%5D%20--%3E%20API%5B%22SQLite%20API%22%5D%0A%20%20API%20--%3E%20PGR%5B%22B%2B%20%E9%A1%B5%22%5D%0A%20%20API%20--%3E%20JRN%5B%22rollback%20%E6%88%96%20WAL%22%5D%0A%20%20PGR%20--%3E%20FILE%5B%22%E5%8D%95%E4%B8%AA%E5%BA%93%E6%96%87%E4%BB%B6%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>恢复：journal 或 WAL 重放，影子课已对照。RTO 极短。无半同步。分析：可把文件当只读副本。不适合多机写。</p><p>计划：<code>EXPLAIN QUERY PLAN</code> 仍看索引是否覆盖。回归同样发生。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲星型模式。也不把 SQLite 当 HTAP 集群。补层数据模型在此收：KV、文档、宽列、图、时序、向量、搜索、嵌入式关系。</p><p>后课默认：单机嵌入用 SQLite 合同（单写者 WAL）。星型模式：分析库的维表事实表，反规范化受控。</p><p>嵌入式把连接池、网络读己之写全部删掉，锁与 WAL 留下。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SQLite：文件即库，B+ 与 WAL/journal，单写者为主。</li><li>SQL 声明仍在；分布式协议不在。</li><li>下一单元星型模式：分析建模。</li><li>出处：SQLite 文档；Gray；本课存储对照。</li></ul>',9))])}const f=o(h,[["render",A]]);export{B as __pageData,f as default};
